#include <bits/stdc++.h>
using namespace std;
struct Seg{int n;vector<long long> tr,lz;Seg(vector<long long>&a){n=(int)a.size()-1;tr.assign(4*n+4,0);lz.assign(4*n+4,0);build(1,1,n,a);}void build(int p,int l,int r,vector<long long>&a){if(l==r){tr[p]=a[l];return;}int m=(l+r)/2;build(p*2,l,m,a);build(p*2+1,m+1,r,a);tr[p]=tr[p*2]+tr[p*2+1];}void add(int p,int l,int r,int ql,int qr,long long v){if(ql<=l&&r<=qr){tr[p]+=v*(r-l+1);lz[p]+=v;return;}int m=(l+r)/2;if(ql<=m)add(p*2,l,m,ql,qr,v);if(qr>m)add(p*2+1,m+1,r,ql,qr,v);tr[p]=tr[p*2]+tr[p*2+1]+lz[p]*(r-l+1);}long long sum(int p,int l,int r,int ql,int qr,long long carry=0){if(ql<=l&&r<=qr)return tr[p]+carry*(r-l+1);int m=(l+r)/2;carry+=lz[p];long long z=0;if(ql<=m)z+=sum(p*2,l,m,ql,qr,carry);if(qr>m)z+=sum(p*2+1,m+1,r,ql,qr,carry);return z;}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;if(!(cin>>n>>m))return 0;vector<long long>a(n+1);for(int i=1;i<=n;i++)cin>>a[i];Seg st(a);while(m--){int op,l,r;cin>>op>>l>>r;if(op==1){long long k;cin>>k;st.add(1,1,n,l,r,k);}else cout<<st.sum(1,1,n,l,r)<<endl;}return 0;}